import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"십육국 핵심 인물","description":"","frontmatter":{},"headers":[],"relativePath":"world/Core-Characters.md","filePath":"world/Core-Characters.md"}'),t={name:"world/Core-Characters.md"};function o(h,l,s,n,u,d){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="십육국-핵심-인물" tabindex="-1">십육국 핵심 인물 <a class="header-anchor" href="#십육국-핵심-인물" aria-label="Permalink to &quot;십육국 핵심 인물&quot;">​</a></h1><p>국가는 스스로 결정을 내리지 않습니다. 전쟁, 동맹, 배신, 구휼, 계승과 병합은 이름 있는 인물이 직위를 통해 제안하고 다른 인물이 승인하거나 거부한 결과입니다.</p><h2 id="작명과-모티프-원칙" tabindex="-1">작명과 모티프 원칙 <a class="header-anchor" href="#작명과-모티프-원칙" aria-label="Permalink to &quot;작명과 모티프 원칙&quot;">​</a></h2><ul><li>기본 이름은 <code>성 1자 + 이름 1~2자</code>의 한국어 형태를 사용합니다. 캠페인 중 새로 생기는 인물은 <a href="/world/Heirs-Names-and-World-Ledger.html">후계, 이름 로스터, 세계 원장</a>의 문화 칸에서 고릅니다.</li><li>왕, 최고 통치자, 오래된 명문을 자처하는 인물은 외자 이름을 선호할 수 있지만 의무는 아닙니다.</li><li>아나그램은 글자 순서만 바꾸는 방식이 아닙니다. 음운 변형, 다른 성씨, 다른 시대의 직업·성격 모티프를 섞어 원형을 직접 식별할 수 없게 합니다.</li><li>일본 전국시대 인물 모티프도 한국어 성명과 서울의 생업·직위로 완전히 재구성합니다.</li><li>한 인물은 최소 두 시대의 성격 모티프와 하나의 서울 생업을 합성합니다.</li><li>실존 인물의 대표 대사, 가족관계, 생애 순서, 대표 전투와 외형을 그대로 옮기지 않습니다.</li></ul><h2 id="강국-핵심-인물" tabindex="-1">강국 핵심 인물 <a class="header-anchor" href="#강국-핵심-인물" aria-label="Permalink to &quot;강국 핵심 인물&quot;">​</a></h2><h3 id="인물-한재목" tabindex="-1">인물 한재목 <a class="header-anchor" href="#인물-한재목" aria-label="Permalink to &quot;인물 한재목&quot;">​</a></h3><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/portraits/hanjaemok.png?raw=true" alt="급수총재 한재목의 흉상 초상"></p><ul><li>소속: 여의신정수문정부</li><li>직위: 급수총재</li><li>성격: 신중하고 계산적이며 약속 문구를 집요하게 지킨다. 사람보다 계약을 더 오래 믿는다.</li><li>개인 야망: 서부의 모든 급수계약을 하나의 수문헌장으로 묶고 종신 조정자가 된다.</li><li>공포: 정수 중단보다 배급구역 대표들이 독자 급수권을 갖는 것을 더 두려워한다.</li><li>통치 방식: 수치와 장부를 공개하지만 계약 위반자에게 집단 단수라는 가혹한 제재를 가한다.</li><li>핵심 관계: 강민서와는 부품 동맹, 오해린과는 가격 공개를 둘러싼 경쟁, 윤서린과는 계약 인준권 분쟁.</li><li>촉발 사건: 뚝도 총관 실종으로 중앙 급수계약이 만료되자 서부 보호권 확대안을 준비한다.</li><li>플레이어 개입: 누락된 배급 장부를 찾아 그의 신뢰를 얻거나, 집단 단수 명령의 피해를 폭로할 수 있다.</li></ul><h3 id="인물-강민서" tabindex="-1">인물 강민서 <a class="header-anchor" href="#인물-강민서" aria-label="Permalink to &quot;인물 강민서&quot;">​</a></h3><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/portraits/gangminseo.png?raw=true" alt="제작평의회 중재자 강민서의 흉상 초상"></p><ul><li>소속: 서남제작동맹</li><li>직위: 제작평의회 중재자</li><li>성격: 대담하고 실용적이며 계급보다 숙련을 존중한다. 공개 토론에서는 온화하지만 합의 뒤의 태업은 용서하지 않는다.</li><li>개인 야망: 서울 전역의 수리 규격과 복구복무자의 시민권을 동시에 통일한다.</li><li>공포: 경비대가 노동조합을 제압해 제작동맹을 군수독재로 바꾸는 것.</li><li>통치 방식: 이해집단의 교환을 설계하고 누구도 독점하지 못하도록 생산 공정을 여러 조합에 나눈다.</li><li>핵심 관계: 한재목에게 펌프 부품을 공급하고, 서이안과 기술 공개 범위를 다투며, 백온의 난민 시민권 요구를 지지한다.</li><li>촉발 사건: 암사고덕상수단이 부품 대신 복구복무자 등록을 요구하면서 내부 경비대가 강경론을 편다.</li><li>플레이어 개입: 파업 중인 공방을 중재하거나 경비대의 비밀 무기 생산을 조사할 수 있다.</li></ul><h3 id="인물-서이안" tabindex="-1">인물 서이안 <a class="header-anchor" href="#인물-서이안" aria-label="Permalink to &quot;인물 서이안&quot;">​</a></h3><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/portraits/seoian.png?raw=true" alt="생명안전 연구책임자 서이안의 흉상 초상"></p><ul><li>소속: 마곡연구평의회</li><li>직위: 생명안전 연구책임자</li><li>성격: 원칙적이고 호기심이 강하며 위험한 실험보다 검증되지 않은 권위를 싫어한다.</li><li>개인 야망: 기술자와 연구자료를 국가 소유물이 아닌 서울 공동재산으로 인정시키는 기술원장을 만든다.</li><li>공포: 보호를 명분으로 연구자가 인질·세습 직능집단이 되는 것.</li><li>통치 방식: 모든 결론에 재현 가능한 기록을 요구하고 긴급 상황에서도 안전심사관의 거부권을 인정한다.</li><li>핵심 관계: 정유라와 공개 계약을 설계하고, 배우진의 군사감독 요구를 거부하며, 임초원을 유력한 기술 후계자로 평가한다.</li><li>촉발 사건: 뚝도 수질 검사망이 멈추자 연구자 파견과 후계 인준이 하나의 거래가 된다.</li><li>플레이어 개입: 오염 표본을 회수하거나 연구 결과를 독점하려는 평의원을 설득할 수 있다.</li></ul><h3 id="인물-임하준" tabindex="-1">인물 임하준 <a class="header-anchor" href="#인물-임하준" aria-label="Permalink to &quot;인물 임하준&quot;">​</a></h3><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/portraits/imhajun.png?raw=true" alt="펌프기술 총관 임하준의 흉상 초상"></p><ul><li>소속: 뚝도공방연합</li><li>직위: 펌프기술 총관, 현재 실종</li><li>성격: 인내심이 강하고 사람의 숙련을 잘 기억하지만 후계를 명확히 말하지 않는 습관이 있다.</li><li>개인 야망: 물과 부품 규격을 통합해 어느 국가도 단독으로 서울의 생명선을 끊지 못하게 한다.</li><li>공포: 자신의 기술가문이 공방평의회를 밀어내 세습국가가 되는 것.</li><li>통치 방식: 서로 경쟁하는 공방에 핵심 공정을 나눠 맡기고 마지막 조립법만 직접 보관했다.</li><li>핵심 관계: 양자 임초원을 아끼지만 공개 지명하지 않았고, 한재목과 급수계약을 맺었으며, 배우진의 보호 제안을 거절했다.</li><li>촉발 사건: 개막 직전 정수 펌프 점검 중 사라지고 세 종류의 상충하는 유언이 발견된다.</li><li>플레이어 개입: 생존 흔적, 진짜 유언, 실종 공모자를 추적할 수 있다.</li></ul><h3 id="인물-배우진" tabindex="-1">인물 배우진 <a class="header-anchor" href="#인물-배우진" aria-label="Permalink to &quot;인물 배우진&quot;">​</a></h3><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/portraits/baeujin.png?raw=true" alt="상수호위사령 배우진의 흉상 초상"></p><ul><li>소속: 암사고덕상수단</li><li>직위: 상수호위사령</li><li>성격: 규율과 속도를 중시하고 위기 때 토론을 약점으로 본다. 부하의 가족까지 책임지지만 이탈은 배신으로 간주한다.</li><li>개인 야망: 동부 급수망을 군사적으로 통합하고 자신이 설계한 보호정부 아래 안정시킨다.</li><li>공포: 민간 행정관이 물을 정치적 거래에 써서 동부가 다시 혼란에 빠지는 것.</li><li>통치 방식: 복구 실적과 치안을 공개하지만 비밀 장교 인맥으로 공식 명령망을 우회한다.</li><li>핵심 관계: 고서준에게 후견을 제안하고, 장세화의 중립을 불신하며, 강민서를 필요한 경쟁자로 본다.</li><li>촉발 사건: 임하준 실종을 뚝도의 통치 실패로 규정하고 보호군 파견안을 낸다.</li><li>플레이어 개입: 군사 개입을 지원하거나 비밀 장교 결사의 명단을 기록청에 넘길 수 있다.</li></ul><h3 id="인물-임초원" tabindex="-1">인물 임초원 <a class="header-anchor" href="#인물-임초원" aria-label="Permalink to &quot;인물 임초원&quot;">​</a></h3><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/portraits/imchowon.png?raw=true" alt="펌프기술자 임초원의 흉상 초상"></p><ul><li>소속: 뚝도공방연합·마곡연구평의회 사이</li><li>직위: 펌프기술자, 임하준의 양자</li><li>성격: 침착하고 관찰력이 뛰어나지만 어느 공동체에도 완전히 속하지 못한다는 불안을 숨긴다.</li><li>개인 야망: 혈통이 아니라 기술과 공방의 동의로 총관이 될 수 있음을 증명한다.</li><li>공포: 자신이 강국들의 타협용 꼭두각시 후계자가 되는 것.</li><li>통치 방식: 공개 설계와 다중 승인으로 권력을 분산하려 한다.</li><li>핵심 관계: 서이안의 제자, 임하준의 양자, 공방대표 한소미의 경쟁자, 배우진이 세우려는 보호정부의 명목 후보.</li><li>촉발 사건: 실종된 총관의 암호화된 정비일지가 임초원만 읽을 수 있는 형식으로 발견된다.</li><li>플레이어 개입: 그의 정통성을 세우거나 유언 조작 의혹을 밝혀 다른 후보를 밀 수 있다.</li></ul><h2 id="약소국-핵심-인물" tabindex="-1">약소국 핵심 인물 <a class="header-anchor" href="#약소국-핵심-인물" aria-label="Permalink to &quot;약소국 핵심 인물&quot;">​</a></h2><h3 id="인물-윤서린" tabindex="-1">인물 윤서린 <a class="header-anchor" href="#인물-윤서린" aria-label="Permalink to &quot;인물 윤서린&quot;">​</a></h3><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/portraits/yunseorin.png?raw=true" alt="기록총재 윤서린의 흉상 초상"></p><ul><li>소속: 도성기록청</li><li>직위: 기록청장</li><li>성격: 냉정하고 예의 바르며 기록되지 않은 약속을 인정하지 않는다.</li><li>개인 야망: 모든 계승과 조약의 최종 인준권을 기록청에 귀속한다.</li><li>공포: 위조된 기록 한 장이 도성의 마지막 권위를 무너뜨리는 것.</li><li>통치 방식: 공개 기록과 비공개 증언을 교차검증한다.</li><li>핵심 관계: 임하준의 유언을 보관했고, 남윤경에게 배급 원장을 의존하며, 문가람과 진실 공개 시점을 다툰다.</li><li>촉발 사건: 서로 다른 세 개의 총관 유언장이 동시에 접수된다.</li><li>플레이어 개입: 증인을 호송하거나 청장 자신의 누락 기록을 찾아 협상할 수 있다.</li></ul><h3 id="인물-박태겸" tabindex="-1">인물 박태겸 <a class="header-anchor" href="#인물-박태겸" aria-label="Permalink to &quot;인물 박태겸&quot;">​</a></h3><ul><li>소속: 용산철도후국</li><li>직위: 철도조정관</li><li>성격: 다정한 후견인처럼 보이지만 모든 관계를 장기 배차표처럼 계산한다.</li><li>개인 야망: 혈연 선로가문의 거부권을 없애고 양자·도제 승계를 정착시킨다.</li><li>공포: 용산이 강국들의 전쟁터가 되어 중계국 지위를 잃는 것.</li><li>통치 방식: 어느 편에도 독점 열차를 주지 않고 상호 인질 대신 도제 교환을 쓴다.</li><li>핵심 관계: 김도윤과 기술자 교환, 한재목과 서부 철도계약, 임초원에게 비밀 후계 제안.</li><li>촉발 사건: 용산 선로가문이 임초원의 귀환 열차를 억류한다.</li><li>플레이어 개입: 열차를 탈환하거나 가문회의에서 양자 승계를 지지할 수 있다.</li></ul><h3 id="인물-오해린" tabindex="-1">인물 오해린 <a class="header-anchor" href="#인물-오해린" aria-label="Permalink to &quot;인물 오해린&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 냉동상인 대표</li><li>성격: 사교적이고 재치 있지만 손실을 숨기는 사람을 가장 잔인하게 몰아붙인다.</li><li>개인 야망: 물·전력·식량 계약을 교환할 수 있는 서울 공통 결제권을 발행한다.</li><li>공포: 냉동 설비가 멈춰 상회의 신용이 하루 만에 사라지는 것.</li><li>통치 방식: 가격과 재고를 공개하고 호송권은 비공개 경매에 붙인다.</li><li>핵심 관계: 남윤경과 가격 주도권 경쟁, 한재목과 전력·물 계약, 문가람에게 시세 방송을 맡긴다.</li><li>촉발 사건: 정전으로 냉동창고의 식량이 상하기 시작한다.</li><li>플레이어 개입: 발전 부품을 구하거나 재고 은폐를 폭로할 수 있다.</li></ul><h3 id="인물-문가람" tabindex="-1">인물 문가람 <a class="header-anchor" href="#인물-문가람" aria-label="Permalink to &quot;인물 문가람&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 방송검증관</li><li>성격: 회의적이고 끈질기며, 진실을 공개하는 것과 사람을 살리는 것이 충돌할 때 오래 망설인다.</li><li>개인 야망: 어떤 강국도 끌 수 없는 다중 송신망을 구축한다.</li><li>공포: 공사가 사실 검증기관이 아니라 승자의 선전국이 되는 것.</li><li>통치 방식: 두 개 이상의 독립 증언이 있어야 공식 방송한다.</li><li>핵심 관계: 윤서린과 기록 공유, 장세화와 의료속보 협약, 배우진과 검열 갈등.</li><li>촉발 사건: 임하준이 실종 전 남긴 음성기록의 편집 흔적을 발견한다.</li><li>플레이어 개입: 원본 송신기를 회수하거나 진실 공개를 늦춰 폭동을 막을 수 있다.</li></ul><h3 id="인물-백온" tabindex="-1">인물 백온 <a class="header-anchor" href="#인물-백온" aria-label="Permalink to &quot;인물 백온&quot;">​</a></h3><ul><li>소속: 북산피난연맹</li><li>직위: 난민대표</li><li>성격: 자비롭지만 완고하며 가족 분리를 정당화하는 어떤 효율론도 거부한다.</li><li>개인 야망: 군사호적과 강제 복구복무에서 벗어난 독립 시민권을 만든다.</li><li>공포: 피난민이 강국의 병력·노동력 숫자로만 기록되는 것.</li><li>통치 방식: 가족 단위 투표와 공개 배급표를 고집한다.</li><li>핵심 관계: 강민서와 시민권 동맹, 배우진과 강제복무 갈등, 류은비에게 의료 지원을 빚졌다.</li><li>촉발 사건: 암사 순찰대가 북산 가족들의 급수권을 복무계약과 묶는다.</li><li>플레이어 개입: 가족 명부를 되찾거나 자발 복무 헌장을 협상할 수 있다.</li></ul><h3 id="인물-김도윤" tabindex="-1">인물 김도윤 <a class="header-anchor" href="#인물-김도윤" aria-label="Permalink to &quot;인물 김도윤&quot;">​</a></h3><ul><li>소속: 창동차륜방</li><li>직위: 차량기지 원로</li><li>성격: 과묵하고 공정하지만 숙련을 증명하지 못한 사람에게 냉정하다.</li><li>개인 야망: 혈통 승계를 폐지하고 공개 기술시험으로 다음 원로를 뽑는다.</li><li>공포: 인구가 많은 주거대표가 기술 안전을 무시하고 기지를 장악하는 것.</li><li>통치 방식: 작업 기록과 사고 책임을 중시한다.</li><li>핵심 관계: 박태겸과 도제 교환, 장세화와 북부 호송, 한재목과 물 공급 협상.</li><li>촉발 사건: 유력 후계자의 시험 부품에서 의도적 결함이 발견된다.</li><li>플레이어 개입: 시험을 감독하거나 조작 배후를 추적할 수 있다.</li></ul><h3 id="인물-장세화" tabindex="-1">인물 장세화 <a class="header-anchor" href="#인물-장세화" aria-label="Permalink to &quot;인물 장세화&quot;">​</a></h3><ul><li>소속: 신내망우환승시</li><li>직위: 배차의무관</li><li>성격: 낙관적이고 협력적이지만 중립을 해치는 무장 집단에는 단호하다.</li><li>개인 야망: 약소국 공동호송조약으로 강국의 보호비를 끝낸다.</li><li>공포: 의료열차가 군수열차로 오인되어 중립이 붕괴하는 것.</li><li>통치 방식: 교통조와 의료조가 번갈아 승인하게 한다.</li><li>핵심 관계: 류은비와 의료동맹, 김도윤과 북부 선로협력, 배우진의 보호 제안을 거절했다.</li><li>촉발 사건: 의료열차에서 암사제 무기가 발견된다.</li><li>플레이어 개입: 밀수범을 찾거나 사건을 조작해 중립을 무너뜨릴 수 있다.</li></ul><h3 id="인물-류은비" tabindex="-1">인물 류은비 <a class="header-anchor" href="#인물-류은비" aria-label="Permalink to &quot;인물 류은비&quot;">​</a></h3><ul><li>소속: 약령의정동맹</li><li>직위: 치료길드 대표</li><li>성격: 자비롭고 원칙적이지만 치료 중립을 위협하는 사람에게는 거래를 끊는다.</li><li>개인 야망: 의약품을 전리품으로 삼지 못하게 하는 서울 의료헌장을 만든다.</li><li>공포: 강국 하나가 약재·항생제 구매를 독점하는 것.</li><li>통치 방식: 환자 중증도와 공개 기여도를 함께 고려한다.</li><li>핵심 관계: 백온에게 생명의 빚, 장세화와 의료호송, 서이안과 약효 검증 협력.</li><li>촉발 사건: 가짜 약품이 북산 피난민에게 퍼지고 제조자가 강국 보호를 받는다.</li><li>플레이어 개입: 제조망을 추적하거나 중립을 깨고 보호국의 창고를 급습할 수 있다.</li></ul><h3 id="인물-고서준" tabindex="-1">인물 고서준 <a class="header-anchor" href="#인물-고서준" aria-label="Permalink to &quot;인물 고서준&quot;">​</a></h3><ul><li>소속: 아차구의관문국</li><li>직위: 능선수비대장</li><li>성격: 신의가 강하고 직선적이지만 기술자 회의를 지나치게 느리다고 여긴다.</li><li>개인 야망: 수비대와 물 기술자를 하나의 관문군으로 통합한다.</li><li>공포: 내부 분열로 동부 교량과 급수권을 동시에 잃는 것.</li><li>통치 방식: 전시 단독지휘, 평시 공동승인을 주장한다.</li><li>핵심 관계: 배우진의 후견 제안, 장세화와 통행 협약, 물 기술자 대표와 권한 갈등.</li><li>촉발 사건: 교량 정찰대가 상수관 파손을 적대행위로 오인한다.</li><li>플레이어 개입: 파손 원인을 밝히거나 전시권한을 한쪽에 몰아줄 수 있다.</li></ul><h3 id="인물-남윤경" tabindex="-1">인물 남윤경 <a class="header-anchor" href="#인물-남윤경" aria-label="Permalink to &quot;인물 남윤경&quot;">​</a></h3><ul><li>소속: 가락잠실배급국</li><li>직위: 경매조정인</li><li>성격: 친절하고 유연하지만 사람의 약점을 가격처럼 기억한다.</li><li>개인 야망: 식량을 가진 자가 아니라 식량의 가격과 배급 순서를 정하는 자가 서울의 왕을 고르게 한다.</li><li>공포: 생산국들이 직거래를 시작해 배급국이 불필요해지는 것.</li><li>통치 방식: 공개 경매 뒤 비공개 비상배급을 병행한다.</li><li>핵심 관계: 오해린과 시장 경쟁, 윤서린과 배급 원장 교환, 배우진에게 동부 군량을 공급한다.</li><li>촉발 사건: 흉작 소문만으로 가격이 폭등하고 내부 상인이 창고를 봉쇄한다.</li><li>플레이어 개입: 실제 재고를 공개하거나 특정 후계자에게 비밀 군량을 넘길 수 있다.</li></ul><h3 id="인물-정유라" tabindex="-1">인물 정유라 <a class="header-anchor" href="#인물-정유라" aria-label="Permalink to &quot;인물 정유라&quot;">​</a></h3><ul><li>소속: 수서강남협약도시</li><li>직위: 계약감사관</li><li>성격: 합리적이고 절제돼 있으며 법보다 힘이 앞서는 순간을 개인적 패배로 여긴다.</li><li>개인 야망: 11개 약소국의 공동교섭권과 손실보상 규칙을 만든다.</li><li>공포: 약소국 연합이 강국 하나의 대리세력으로 전락하는 것.</li><li>통치 방식: 모든 조약에 종료조건, 감사권, 인질 대체 보증을 넣는다.</li><li>핵심 관계: 서이안과 기술공유 계약, 윤서린과 인준권 경쟁, 장세화와 약소국 회의 준비.</li><li>촉발 사건: 세 강국이 서로 다른 급수계약을 약소국에 동시에 강요한다.</li><li>플레이어 개입: 협약 초안을 운반하거나 서명자를 협박하는 세력을 제거할 수 있다.</li></ul><h2 id="인물이-결정을-만드는-규칙" tabindex="-1">인물이 결정을 만드는 규칙 <a class="header-anchor" href="#인물이-결정을-만드는-규칙" aria-label="Permalink to &quot;인물이 결정을 만드는 규칙&quot;">​</a></h2><p>세계 상태는 전쟁을 자동으로 만들지 않고 쟁점을 만듭니다. 식량 부족은 배급·교역·징발·약탈이라는 후보를 만들고, 담당 인물이 성격, 야망, 공포, 관계, 기억과 직위 권한으로 후보를 평가합니다.</p><p>모든 국가 행동은 다음 질문에 답할 수 있어야 합니다.</p><ol><li>누가 제안했는가?</li><li>어떤 직위가 권한을 주었는가?</li><li>무엇을 얻거나 두려워했는가?</li><li>누가 승인하거나 거부했는가?</li><li>어떤 관계와 기억이 판단을 바꾸었는가?</li><li>그 결정이 다음 쟁점과 인물 관계를 어떻게 만들었는가?</li></ol><p>답할 수 없는 전쟁, 동맹, 배신과 계승은 발생시키지 않습니다.</p>',52)])])}const m=i(t,[["render",o]]);export{b as __pageData,m as default};
